import type { JSX } from 'solid-js'

/**
 * The states fixture: a Solid member's `*.states.tsx`, generated by
 * `pnpm shells` from the member's description (`packages/shells/src/members/`).
 *
 * The entries carry the React fixture's names, so a contract's `when <state>`
 * names the same entry in every shell. `render` takes the props the
 * conformance runner sets on the member (a probe name, a spy in a handler),
 * over the fixture's own.
 */
export interface StateEntry {
  name: string
  render: (overrides?: Readonly<Record<string, unknown>>) => JSX.Element
  /** Attributes the rendered root must carry. `null` asserts absence. */
  expect?: Record<string, string | null>
  /** The entry renders nothing at all, by design. */
  rendersNothing?: true
}

export interface ComponentStates {
  component: string
  entries: StateEntry[]
}
